"""Self-Improvement Log: structured proposals generated by the agent about its own behavior."""

import json
import logging
from datetime import datetime, UTC
from pathlib import Path
from typing import Optional

logger = logging.getLogger(__name__)

SELF_IMPROVEMENT_LOG_PATH = Path("data/self_improvement_log.jsonl")
_proposal_counter: int = 0


def _next_proposal_id() -> str:
    global _proposal_counter
    _proposal_counter += 1
    return f"P-{_proposal_counter:03d}"


def log_proposal(source: str, summary: str, details: Optional[str] = None) -> str:
    """Append a self-improvement proposal to the JSONL log.

    Returns the proposal_id.
    """
    pid = _next_proposal_id()
    entry = {
        "timestamp": datetime.now(UTC).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "source": source,
        "proposal_id": pid,
        "summary": summary,
        "details": details or "",
        "status": "pending",
    }
    SELF_IMPROVEMENT_LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
    try:
        with open(str(SELF_IMPROVEMENT_LOG_PATH), "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
        logger.info("Self-improvement: proposal %s logged (source=%s)", pid, source)
    except Exception as e:
        logger.warning("Self-improvement: error logging proposal: %s", e)
    return pid


def mark_proposal_applied(proposal_id: str) -> bool:
    """Mark a proposal as applied. Rewrites the entire log file."""
    if not SELF_IMPROVEMENT_LOG_PATH.exists():
        return False
    try:
        lines = SELF_IMPROVEMENT_LOG_PATH.read_text(encoding="utf-8").splitlines()
        updated = []
        found = False
        for line in lines:
            entry = json.loads(line)
            if entry.get("proposal_id") == proposal_id:
                entry["status"] = "applied"
                found = True
            updated.append(json.dumps(entry, ensure_ascii=False))
        if found:
            SELF_IMPROVEMENT_LOG_PATH.write_text(
                "\n".join(updated) + "\n", encoding="utf-8"
            )
            logger.info("Self-improvement: proposal %s marked as applied", proposal_id)
        return found
    except Exception as e:
        logger.warning("Self-improvement: error marking proposal %s: %s", proposal_id, e)
        return False


def list_proposals(status: Optional[str] = None) -> list:
    """Return all proposals, optionally filtered by status."""
    if not SELF_IMPROVEMENT_LOG_PATH.exists():
        return []
    proposals = []
    try:
        for line in SELF_IMPROVEMENT_LOG_PATH.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line:
                entry = json.loads(line)
                if status is None or entry.get("status") == status:
                    proposals.append(entry)
    except Exception as e:
        logger.warning("Self-improvement: error reading log: %s", e)
    return proposals
